BEGIN;
ALTER TABLE public.redirect_link_tags DROP CONSTRAINT redirect_link_tags_pending_tenant_fence;
SET LOCAL ROLE service_role;
DO $$
DECLARE owner_id uuid:=gen_random_uuid();human uuid:=gen_random_uuid();editor uuid:=gen_random_uuid();recipient uuid:=gen_random_uuid();other uuid:=gen_random_uuid();foreign_tag uuid;billing uuid;member uuid;folder uuid;link_id uuid;key uuid;tag uuid;r jsonb;
BEGIN
 INSERT INTO auth.users(id,email,email_confirmed_at) VALUES(owner_id,'billing-owner@example.org',now()),(human,'billing-human@example.org',now()),(editor,'billing-editor@example.org',now()),(recipient,'billing-invite@example.org',now());
 INSERT INTO public.user_roles VALUES(owner_id,'admin');
 INSERT INTO public.redirect_workspaces(id,name,slug) VALUES(other,'Billing tag isolation','billing-tag-isolation');
 INSERT INTO public.redirect_link_tags(workspace_id,name,color) VALUES(other,'Member tag','pink') RETURNING id INTO foreign_tag;
 r:=public.redirect_member_administration(owner_id,'create',p_values=>jsonb_build_object('label','Billing teammate','kind','user','user_id',human,'role','billing'));billing:=(r->>'id')::uuid;
 IF r->>'role'<>'billing' OR public.redirect_workspace_context(human)#>>'{principal,role}'<>'billing' THEN RAISE EXCEPTION 'Billing role admission or session lost';END IF;
 INSERT INTO public.redirect_workspace_members(user_id,kind,label) VALUES(editor,'user','Tag editor') RETURNING id INTO member;
 INSERT INTO public.redirect_link_folders(name,default_permission) VALUES('Billing owner override','none') RETURNING id INTO folder;
 INSERT INTO public.redirect_folder_members VALUES(folder,billing,'owner');
 r:=public.redirect_management_mutate(jsonb_build_array(jsonb_build_object('operation','create','data',jsonb_build_object('slug','billing-role-fixture','target','https://example.org/billing','folderId',folder))));link_id:=(r->0->'link'->>'id')::uuid;
 IF public.redirect_folder_rank(billing,folder)<>1 OR (public.redirect_folder_capabilities(folder,billing)->>'canManage')::boolean OR (public.redirect_management_list(p_token_id=>billing)#>>'{data,0,canEdit}')::boolean THEN RAISE EXCEPTION 'Billing folder override acquired write authority';END IF;
 BEGIN PERFORM public.redirect_management_mutate(jsonb_build_array(jsonb_build_object('operation','update','id',link_id,'data',jsonb_build_object('comment','denied'))),billing);RAISE EXCEPTION 'Billing member edited link';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_folder_access(folder,'{"defaultPermission":"edit"}',billing);RAISE EXCEPTION 'Billing member edited folder ACL';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_workspace_resource('folders','create',p_values=>'{"name":"Denied billing folder"}',p_token_id=>billing);RAISE EXCEPTION 'Billing member created folder';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_workspace_resource('tags','create',p_values=>'{"name":"Denied billing tag"}',p_token_id=>billing);RAISE EXCEPTION 'Billing member created tag';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_workspace_resource('templates','create',p_values=>'{"name":"Denied billing template"}',p_token_id=>billing);RAISE EXCEPTION 'Billing member created template';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.redirect_member_administration(human,'list');RAISE EXCEPTION 'Billing member acquired owner administration';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 INSERT INTO public.redirect_api_tokens(name,token_hash,prefix,scopes,member_id,created_by,expires_at) VALUES('Billing bound key',repeat('a',64),'fixture',ARRAY['links:read','links:write','events:read','workspace:read','workspace:write'],billing,owner_id,now()+interval '1 day') RETURNING id INTO key;
 IF public.redirect_management_scope(key,'links:write') IS DISTINCT FROM ARRAY[]::uuid[] OR public.redirect_management_scope(key,'links:read') IS DISTINCT FROM ARRAY[link_id] THEN RAISE EXCEPTION 'Bound key bypassed billing role cap';END IF;
 BEGIN PERFORM public.redirect_workspace_resource('tags','create',p_values=>'{"name":"Denied billing key tag"}',p_token_id=>key);RAISE EXCEPTION 'Billing key created tag';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.redirect_workspace_resource('tags','create',p_values=>'{"name":"Member tag","color":"purple"}',p_token_id=>member);tag:=(r->>'id')::uuid;
 BEGIN PERFORM public.redirect_workspace_resource('tags','update',foreign_tag,'{"name":"Denied foreign tag"}',p_token_id=>member);RAISE EXCEPTION 'Member edited foreign workspace tag';EXCEPTION WHEN no_data_found THEN NULL;END;
 BEGIN PERFORM public.redirect_workspace_resource('tags','delete',foreign_tag,p_token_id=>member);RAISE EXCEPTION 'Member deleted foreign workspace tag';EXCEPTION WHEN no_data_found THEN NULL;END;
 r:=public.redirect_workspace_resource('tags','update',tag,'{"name":"Member renamed tag","color":"blue"}',p_token_id=>member);
 IF r->>'name'<>'Member renamed tag' OR r->>'color'<>'blue' THEN RAISE EXCEPTION 'Member tag edit lost fields';END IF;
 BEGIN PERFORM public.redirect_workspace_resource('tags','delete',tag,p_token_id=>billing);RAISE EXCEPTION 'Billing member deleted tag';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF NOT(public.redirect_workspace_resource('tags','delete',tag,p_token_id=>member)->>'deleted')::boolean THEN RAISE EXCEPTION 'Member tag delete denied';END IF;
 IF NOT EXISTS(SELECT FROM public.redirect_link_tags WHERE id=foreign_tag AND workspace_id=other AND name='Member tag' AND color='pink') THEN RAISE EXCEPTION 'Member tag mutation changed foreign tag';END IF;
 UPDATE public.redirect_workspace_members SET role='viewer' WHERE id=member;
 BEGIN PERFORM public.redirect_workspace_resource('tags','create',p_values=>'{"name":"Denied viewer tag"}',p_token_id=>member);RAISE EXCEPTION 'Viewer acquired member tag writes';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 r:=public.redirect_workspace_invitation(owner_id,'create',p_values=>'{"email":"billing-invite@example.org","label":"Invited billing","role":"billing"}',p_hash=>repeat('b',64));
 r:=public.redirect_workspace_invitation(recipient,'accept',p_hash=>repeat('b',64));
 IF r->>'role'<>'billing' THEN RAISE EXCEPTION 'Billing invitation changed role';END IF;
 UPDATE public.redirect_workspace_members SET active=false WHERE id=billing;
 BEGIN PERFORM public.redirect_management_scope(key,'links:read');RAISE EXCEPTION 'Inactive billing credential retained access';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
ROLLBACK;
